    time_1 = self.time
    time_2 = track_point.time

    if time_1 == time_2:
        return 0

    if time_1 > time_2:
        delta = time_1 - time_2
    else:
        delta = time_2 - time_1

    return mod_utils.total_seconds(delta)

def speed_between(self, track_point: 'GPXTrackPoint') ->Optional[float]:
    if not track_point:
        return None

    seconds = self.time_difference(track_point)
